class ProductService {
  final ApiService _apiService = ApiService();

  // Create product
  Future<String> createProduct(ProductModel product, List<XFile> images) async {
    try {
      // Upload images
      List<String> imageUrls = await _uploadImages(images);

      // Create product with image URLs
      // Note: product.id will be generated by the server, so we don't send it or we ignore it
      final productData = product.toMap();
      productData['imageUrls'] = imageUrls;
      
      // We need to ensure the server handles the ID generation or we send a temporary one
      // The PHP script generates a new ID.
      
      final response = await _apiService.post('products/create.php', productData);
      return response['id'];
    } catch (e) {
      print('Create product error: $e');
      rethrow;
    }
  }

