  // Helper: Upload images
  Future<List<String>> _uploadImages(List<XFile> images) async {
    try {
      List<String> urls = [];
      for (var image in images) {
        String url = await _apiService.uploadImage(File(image.path));
        urls.add(url);
      }
      return urls;
    } catch (e) {
